{ source, lockFile, system }:
let
  flake = builtins.getFlake source;
  pkgs = import flake.inputs.nixpkgs {
    inherit system;
    overlays = [ flake.overlays.default ];
  };
in
(pkgs.cabal-purifier.buildCabalProject {
  src = flake.outPath + "/tests/fixtures/app";
  lockFile = /. + lockFile;
}).project

